	@Test
	void telemetryAndRepeatedEvaluationPrepareFreshOccurrenceKeys() {
		List<BindingSet> input = List.of(row(3), row(2), row(1));
		AtomicInteger evaluations = new AtomicInteger();
		FunctionCall key = new FunctionCall("urn:rdf4j:test:order-counter");
		Order node = new Order(new SingletonSet(), new OrderElem(key));
		node.setRuntimeTelemetryEnabled(true);
		OrderComparator comparator = comparator(node, key, evaluations,
				i -> SimpleValueFactory.getInstance().createLiteral(i));
		OrderQueryEvaluationStep step = new OrderQueryEvaluationStep(node, comparator, Long.MAX_VALUE, false,
				ignored -> new CloseableIteratorIteration<>(input.iterator()), 1);
		for (int attempt = 1; attempt <= 2; attempt++) {
			try (CloseableIteration<BindingSet> result = step.evaluate(EmptyBindingSet.getInstance())) {
				assertEquals(input, consume(result));
			}
			assertEquals(attempt * input.size(), evaluations.get());
		}
		assertEquals(6, node.getLongMetricActual(TelemetryMetricNames.ROWS_SORTED_ACTUAL));
		assertEquals(4, node.getLongMetricActual(TelemetryMetricNames.SPILL_COUNT_ACTUAL));
		assertTrue(node.getLongMetricActual(TelemetryMetricNames.SPILL_BYTES_ACTUAL) > 0);
		assertTrue(node.getLongMetricActual(TelemetryMetricNames.SORT_COMPARISONS_ACTUAL) > 0);
	}

