	@Test
	void keyPreparationFailureClosesInputAndDeletesCompletedSpills() throws IOException {
		Set<Path> filesBefore = spillFiles();
		List<BindingSet> input = List.of(row(3), row(2), row(1));
		AtomicInteger evaluations = new AtomicInteger();
		FunctionCall key = new FunctionCall("urn:rdf4j:test:order-counter");
		Order node = new Order(new SingletonSet(), new OrderElem(key));
		OrderComparator comparator = comparator(node, key, evaluations, i -> {
			if (i == 3) {
				throw new IllegalStateException("abandon ORDER key preparation");
			}
			return SimpleValueFactory.getInstance().createLiteral(i);
		});
		CloseableIteratorIteration<BindingSet> source = new CloseableIteratorIteration<>(input.iterator());
		try (OrderIterator result = new OrderIterator(source, comparator, Long.MAX_VALUE, false, 1);
				QueryExecutionContext.Activation ignored = QueryExecutionContext.activateReplaySafepoint(() -> {
				})) {
			assertThrows(IllegalStateException.class, result::hasNext);
			assertTrue(source.isClosed());
		}
		Set<Path> leaked = spillFiles();
		leaked.removeAll(filesBefore);
		assertTrue(leaked.isEmpty(), "completed runs must be deleted after key preparation fails");
	}

	@Test
	void keyPreparationFailureKeepsInputCloseFailureSuppressed() {
		List<BindingSet> input = List.of(row(3), row(2), row(1));
		AtomicInteger evaluations = new AtomicInteger();
		FunctionCall key = new FunctionCall("urn:rdf4j:test:order-counter");
		Order node = new Order(new SingletonSet(), new OrderElem(key));
		IllegalStateException keyFailure = new IllegalStateException("abandon ORDER key preparation");
		IllegalStateException closeFailure = new IllegalStateException("ORDER input close failure");
		OrderComparator comparator = comparator(node, key, evaluations, i -> {
			if (i == 3) {
				throw keyFailure;
			}
			return SimpleValueFactory.getInstance().createLiteral(i);
		});
		CloseableIteratorIteration<BindingSet> source = new CloseableIteratorIteration<>(input.iterator()) {
			@Override
			protected void handleClose() {
				throw closeFailure;
			}
		};
		try (OrderIterator result = new OrderIterator(source, comparator, Long.MAX_VALUE, false, 1)) {
			IllegalStateException failure = assertThrows(IllegalStateException.class, result::hasNext);
			assertSame(keyFailure, failure);
			assertEquals(List.of(closeFailure), List.of(failure.getSuppressed()));
		}
	}

	private static Order findOrder(TupleExpr expression) {
		AtomicReference<Order> result = new AtomicReference<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Order node) {
				result.set(node);
				super.meet(node);
			}
		});
		return result.get();
	}

	private static Set<Path> spillFiles() throws IOException {
		try (Stream<Path> files = Files.list(Path.of(System.getProperty("java.io.tmpdir")))) {
			return files.filter(path -> path.getFileName().toString().startsWith("orderiter"))
					.collect(Collectors.toSet());
		}
	}

	private static OrderComparator comparator(Order node, FunctionCall key, AtomicInteger evaluations,
			IntFunction<Value> values) {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null) {
			@Override
			public QueryValueEvaluationStep precompile(ValueExpr expr, QueryEvaluationContext context) {
				if (expr == key) {
					return bindings -> values.apply(evaluations.incrementAndGet());
				}
				return super.precompile(expr, context);
			}
		};
		return new OrderComparator(strategy, node, new ValueComparator(), new QueryEvaluationContext.Minimal(null));
	}

	private static BindingSet row(int value) {
		MapBindingSet row = new MapBindingSet();
		row.addBinding("value", SimpleValueFactory.getInstance().createLiteral(value));
		return row;
	}

	private static List<BindingSet> consume(CloseableIteration<BindingSet> result) {
		List<BindingSet> rows = new ArrayList<>();
		while (result.hasNext()) {
			BindingSet row = result.next();
			assertTrue(row.getBindingNames().stream().allMatch(name -> name.equals("value")),
					"sort keys must stay outside query-visible bindings");
			rows.add(row);
		}
		return rows;
	}
